const requestId = $('Correction Trigger Webhook').first().json.body.request_id;
const contract = $json.contract;
const review = (contract.stage_artifacts && contract.stage_artifacts.review_result) || { findings: [] };
const rejected = review.findings.filter(f => f.artifact_key);
const attempts = (contract.stage_artifacts && contract.stage_artifacts.correction_attempts) || 0;
const maxAttempts = 3;
const currentManifest = (contract.stage_artifacts && contract.stage_artifacts.build_manifest) || [];
return [{ json: { request_id: requestId, contract, rejected_findings: rejected, attempts, max_attempts: maxAttempts, exceeded: attempts >= maxAttempts, current_manifest: currentManifest } }];

const ctx = $('Increment Attempts').first().json;
const prompt = `Tu es un agent de correction de contenu WordPress. Un reviewer independant a rejete certains artefacts (et seulement ceux-la -- ne touche a rien d'autre).

Findings a corriger: ${JSON.stringify(ctx.rejected_findings)}

Reponds UNIQUEMENT avec un objet JSON de cette forme exacte, sans markdown, sans texte autour, et UNIQUEMENT pour les artifact_key listes ci-dessus:
{"artifacts": [{"artifact_key": "accueil", "title": "Accueil", "post_type": "page", "status": "draft", "content": "<p>...</p>"}]}

Regles: corrige precisement ce que le finding decrit dans expected_correction. content est du HTML simple. Jamais de placeholder non resolu.`;
return [{ json: { request_id: ctx.request_id, prompt } }];

const requestId = $('Build Correction Agent Prompt').first().json.request_id;
const parsed = $json.parsed_json;
const artifacts = (parsed && Array.isArray(parsed.artifacts)) ? parsed.artifacts : [];
return [{ json: { request_id: requestId, artifacts } }];

// Same publication_gate as mcp-tool-policy.json / 20-wordpress-builder, made visible here too.
const { request_id, artifacts } = $json;
const placeholderPatterns = [/\{\{[^}]*\}\}/, /\bTODO\b/, /\bTBD\b/, /\[a completer\]/i, /\[a confirmer\]/i];
const dropped = [];
const accepted = [];
for (const a of artifacts) {
  if (!a.artifact_key || !a.title || typeof a.content !== 'string') {
    dropped.push({ artifact_key: a.artifact_key, reason: 'missing required field' });
    continue;
  }
  if (a.title.length > 200 || a.content.length > 50000) {
    dropped.push({ artifact_key: a.artifact_key, reason: 'exceeds arg_bounds' });
    continue;
  }
  if (!['post', 'page'].includes(a.post_type)) a.post_type = 'page';
  const hasPlaceholder = placeholderPatterns.some(p => p.test(a.content));
  a.status = hasPlaceholder ? 'draft' : (['draft', 'publish'].includes(a.status) ? a.status : 'draft');
  a._placeholder_forced_draft = hasPlaceholder;
  accepted.push(a);
}
return [{ json: { request_id, artifacts: accepted, dropped } }];

const requestId = $json.request_id;
return $json.artifacts.map(a => ({ json: {
  request_id: requestId,
  artifact_key: a.artifact_key,
  title: a.title,
  mcp_request: {
    jsonrpc: '2.0',
    id: requestId + ':correction:' + a.artifact_key,
    method: 'tools/call',
    params: { name: 'upsert_post', arguments: {
      request_id: requestId,
      artifact_key: a.artifact_key,
      title: a.title,
      post_type: a.post_type,
      status: a.status,
      content: a.content
    } }
  }
} }));

return $input.all().map((item, idx) => {
  const callItem = $('Build MCP Call Items').all()[idx].json;
  let upsertResult = null;
  try {
    const text = item.json.result.content[0].text;
    upsertResult = JSON.parse(text);
  } catch (e) {
    upsertResult = { error: 'unparseable upsert response', raw: item.json };
  }
  return { json: { request_id: callItem.request_id, artifact_key: callItem.artifact_key, title: callItem.title, upsert: upsertResult } };
});

return $input.all().map((item, idx) => {
  const prior = $('Parse Upsert Result').all()[idx].json;
  let verified = false;
  let readback = null;
  try {
    readback = JSON.parse(item.json.result.content[0].text);
    verified = readback.ID === prior.upsert.post_id && readback.title === prior.title;
  } catch (e) {
    readback = { error: 'unparseable readback response' };
  }
  return { json: {
    request_id: prior.request_id,
    artifact_key: prior.artifact_key,
    post_id: prior.upsert.post_id,
    action: prior.upsert.action,
    status: readback && readback.status,
    verified
  } };
});

const corrected = $input.all().map(i => i.json);
const ctx = $('Increment Attempts').first().json;
const byKey = new Map(ctx.current_manifest.map(m => [m.artifact_key, m]));
for (const c of corrected) byKey.set(c.artifact_key, c);
return [{ json: { request_id: ctx.request_id, manifest: Array.from(byKey.values()), corrected_keys: corrected.map(c => c.artifact_key), new_attempts: ctx.new_attempts } }];
